        application/json; charset=utf-8

      @{
        return "{\"schema_version\":\"v1\",\"name_for_human\":\"Business Operations Assistant\",\"name_for_model\":\"business_ops\",\"description_for_human\":\"Search products, manage inventory, create and track IT support tickets, and search the knowledge base.\",\"description_for_model\":\"Use these tools to help users with product searches, inventory checks, restock ordering, IT helpdesk ticket management, and knowledge base lookups. Always search the knowledge base before creating a ticket.\",\"auth\":{\"type\":\"service_http\",\"authorization_type\":\"bearer\"},\"api\":{\"type\":\"openapi\",\"url\":\"https://{{apim-host}}/mcp/openapi.json\"},\"tools\":[{\"name\":\"search_products\",\"description\":\"Search the product catalog by keyword and/or category. Returns matching products with pricing and SKU.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"q\":{\"type\":\"string\",\"description\":\"Search keyword\"},\"category\":{\"type\":\"string\",\"description\":\"Filter by category: Electronics, Furniture, Office Supplies\"}}}},{\"name\":\"get_product\",\"description\":\"Get detailed information about a specific product by its ID.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"string\",\"description\":\"The product ID\"}},\"required\":[\"id\"]}},{\"name\":\"check_stock\",\"description\":\"Check the current stock level for a product. Returns available quantity, reorder threshold and warehouse location.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"string\",\"description\":\"The product ID to check stock for\"}},\"required\":[\"id\"]}},{\"name\":\"restock_product\",\"description\":\"Create a restock order for a product that is low on inventory.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"productId\":{\"type\":\"string\",\"description\":\"The product ID to restock\"},\"quantity\":{\"type\":\"integer\",\"description\":\"Number of units to order\"},\"requestedBy\":{\"type\":\"string\",\"description\":\"Name or email of the person requesting the restock\"},\"notes\":{\"type\":\"string\",\"description\":\"Optional notes for the restock order\"}},\"required\":[\"productId\",\"quantity\",\"requestedBy\"]}},{\"name\":\"list_tickets\",\"description\":\"List IT support tickets. Can be filtered by status, priority, or assignee.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"status\":{\"type\":\"string\",\"description\":\"Filter by status: open, in-progress, resolved, closed\"},\"priority\":{\"type\":\"string\",\"description\":\"Filter by priority: low, medium, high, critical\"},\"assignee\":{\"type\":\"string\",\"description\":\"Filter by assigned team member email\"}}}},{\"name\":\"get_ticket\",\"description\":\"Get full details of a specific support ticket by ID.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"string\",\"description\":\"The ticket ID\"}},\"required\":[\"id\"]}},{\"name\":\"create_ticket\",\"description\":\"Create a new IT support ticket. Always search the knowledge base first to see if the issue can be self-resolved.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"title\":{\"type\":\"string\",\"description\":\"Short title describing the issue\"},\"description\":{\"type\":\"string\",\"description\":\"Detailed description of the problem\"},\"priority\":{\"type\":\"string\",\"description\":\"Priority level: low, medium, high, critical\"},\"category\":{\"type\":\"string\",\"description\":\"Category: hardware, software, network, access\"},\"requestedBy\":{\"type\":\"string\",\"description\":\"Email of the person reporting the issue\"}},\"required\":[\"title\",\"description\",\"priority\",\"category\",\"requestedBy\"]}},{\"name\":\"update_ticket_status\",\"description\":\"Update the status of an existing support ticket.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"string\",\"description\":\"The ticket ID to update\"},\"status\":{\"type\":\"string\",\"description\":\"New status: open, in-progress, resolved, closed\"},\"notes\":{\"type\":\"string\",\"description\":\"Notes explaining the status change\"},\"updatedBy\":{\"type\":\"string\",\"description\":\"Email of the person making the update\"}},\"required\":[\"id\",\"status\",\"updatedBy\"]}},{\"name\":\"search_knowledge_base\",\"description\":\"Search the IT knowledge base for articles, how-to guides and troubleshooting steps. Call this before creating a ticket.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"q\":{\"type\":\"string\",\"description\":\"Search query, e.g. 'VPN setup', 'printer not working'\"},\"category\":{\"type\":\"string\",\"description\":\"Optional category filter\"}},\"required\":[\"q\"]}},{\"name\":\"get_kb_article\",\"description\":\"Get the full content of a knowledge base article by ID.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"string\",\"description\":\"The KB article ID\"}},\"required\":[\"id\"]}}]}";
      }








    api://apim-mcp-demo


    https://login.microsoftonline.com/{{tenant-id}}/v2.0
    https://sts.windows.net/{{tenant-id}}/




<rate-limit-by-key calls="60" renewal-period="60"
                   counter-key="@(context.Subscription.Id ?? context.Request.IpAddress)"
                   increment-condition="@(context.Response.StatusCode < 500)" />



  @{
    var path = context.Request.Url.Path;
    var segments = path.Split('/');
    var toolHint = segments.Length > 0 ? segments[segments.Length - 1] : "unknown";
    var subscriptionId = context.Subscription?.Id ?? "anonymous";
    return $"[MCP] tool={toolHint} subscription={subscriptionId} method={context.Request.Method} path={path}";
  }









